import unittest
from checkout import retry

class RetryTests(unittest.TestCase):
    def test_retry(self):
        calls = []
        def send():
            calls.append(1)
            if len(calls) == 1:
                raise TimeoutError()
            return 'ok'
        self.assertEqual(retry(send), 'ok')
        self.assertEqual(len(calls), 2)

