import unittest
from lookup import lookup

class LookupTests(unittest.TestCase):
    def test_invalid_keys(self):
        for key in (None, '', 0):
            with self.subTest(key=key), self.assertRaises(ValueError):
                lookup({'item': 'first'}, key)

    def test_current_value(self):
        values = {'item': 'first'}
        self.assertEqual(lookup(values, 'item'), 'first')
        values['item'] = 'second'
        self.assertEqual(lookup(values, 'item'), 'second')

    def test_dictionary_isolation(self):
        self.assertEqual(lookup({'item': 'left'}, 'item'), 'left')
        self.assertEqual(lookup({'item': 'right'}, 'item'), 'right')

